'use client'

import {
  cn,
  DismissableLayer,
  useAnchorPosition,
  useControllableSignal,
  useSignals,
} from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { useId, useRef } from 'react'
import type { ReactNode } from 'react'
import styles from './toggletip.module.css'

export type ToggletipPlacement =
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'top-start'
  | 'top-end'
  | 'bottom-start'
  | 'bottom-end'

export interface ToggletipProps {
  /** The trigger node (e.g. an info icon). Rendered inside a button. */
  trigger: ReactNode
  /** The popover content. Interactive and selectable. */
  children: ReactNode
  placement?: ToggletipPlacement
  /**
   * Initial open state when uncontrolled
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
  labels?: { label?: string }
  className?: string
}

export function Toggletip({
  trigger,
  children,
  placement = 'top',
  defaultOpen = false,
  open,
  onOpenChange,
  labels,
  className,
}: ToggletipProps) {
  useSignals()
  const [isOpen, setOpen] = useControllableSignal<boolean>({
    ...(open !== undefined && { value: open }),
    defaultValue: defaultOpen,
    ...(onOpenChange && { onChange: onOpenChange }),
  })

  const triggerRef = useRef<HTMLButtonElement>(null)
  const bubbleRef = useRef<HTMLDivElement>(null)
  const bubbleId = useId()

  const { anchorStyle, floatingStyle } = useAnchorPosition({
    anchorRef: triggerRef,
    floatingRef: bubbleRef,
    placement,
    enabled: isOpen,
  })

  return (
    <span className={cn(styles['root'], className)}>
      <button
        ref={triggerRef}
        type="button"
        className={styles['trigger']}
        aria-expanded={isOpen.value}
        aria-controls={bubbleId}
        aria-label={labels?.label ?? t(builtin.toggletip.label)}
        style={anchorStyle}
        onClick={() => setOpen(!isOpen.value)}
      >
        {trigger}
      </button>

      {isOpen.value ? (
        <DismissableLayer onDismiss={() => setOpen(false)}>
          <div
            ref={bubbleRef}
            id={bubbleId}
            role="status"
            data-state="open"
            data-placement={placement}
            className={styles['bubble']}
            style={floatingStyle}
          >
            {children}
          </div>
        </DismissableLayer>
      ) : null}
    </span>
  )
}

@layer cascivo.component {
  .root {
    position: relative;
    display: inline-flex;
  }

  .trigger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--cascivo-space-1);
    background: transparent;
    border: none;
    border-radius: var(--cascivo-radius-control);
    color: inherit;
    cursor: pointer;

    &:hover {
      background: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  .bubble {
    z-index: var(--cascivo-z-tooltip);
    inline-size: max-content;
    max-inline-size: 18rem;
    margin: var(--cascivo-space-2);
    padding-inline: var(--cascivo-space-3);
    padding-block: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-snug);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-overlay);
    box-shadow: var(--cascivo-shadow-md);

    opacity: 1;
    translate: 0 0;
    transition:
      opacity var(--cascivo-motion-enter),
      translate var(--cascivo-motion-enter);

    @starting-style {
      opacity: 0;
      translate: 0 calc(-1 * var(--cascivo-space-1));
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .bubble {
    transition: none;
  }
}

@media (forced-colors: active) {
  .trigger:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }

  .bubble {
    border: 1px solid CanvasText;
    background-color: Canvas;
    color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Toggletip',
  description: 'A click-triggered info popover for supplementary, selectable content',
  category: 'overlay',
  // The content is gated behind the open signal, so it is absent from the server HTML
  // entirely.
  clientJs: 'required',
  states: ['open', 'closed'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'trigger',
      type: 'ReactNode',
      required: true,
      description: 'Trigger content, rendered inside a button (e.g. an info icon)',
    },
    {
      name: 'children',
      type: 'ReactNode',
      required: true,
      description: 'The popover content — interactive and selectable',
    },
    {
      name: 'placement',
      type: "'top' | 'bottom' | 'left' | 'right' | 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end'",
      required: false,
      default: "'top'",
      description: 'Side and alignment of the bubble relative to the trigger',
    },
    {
      name: 'defaultOpen',
      type: 'boolean',
      required: false,
      default: 'false',
      description: 'Initial open state when uncontrolled',
    },
    {
      name: 'open',
      type: 'boolean',
      required: false,
      description: 'Controlled open state',
    },
    {
      name: 'onOpenChange',
      type: '(open: boolean) => void',
      required: false,
      description: 'Called whenever the open state should change',
    },
    {
      name: 'labels',
      type: '{ label?: string }',
      required: false,
      description: 'Override the trigger accessible name',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-text',
    '--cascivo-color-bg-subtle',
    '--cascivo-radius-control',
    '--cascivo-radius-overlay',
    '--cascivo-shadow-md',
    '--cascivo-focus-ring',
    '--cascivo-motion-enter',
    '--cascivo-z-tooltip',
  ],
  accessibility: {
    role: 'status',
    wcag: '2.2-AA',
    keyboard: ['Enter', 'Space', 'Escape'],
    forcedColors: true,
    reducedMotion: true,
  },
  examples: [
    {
      title: 'Info toggletip',
      description: 'An info button that reveals supplementary text on click',
      code: `<Toggletip trigger={<InfoIcon />}>
  Your password must contain at least 12 characters.
</Toggletip>`,
    },
    {
      title: 'Controlled',
      description: 'Drive the open state from the parent',
      code: `<Toggletip
  trigger={<InfoIcon />}
  open={open}
  onOpenChange={setOpen}
  placement="bottom-start"
>
  <a href="/docs">Learn more</a>
</Toggletip>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['overlay', 'toggletip', 'info', 'popover', 'floating'],
  intent: {
    whenToUse: [
      'Revealing brief supplementary information on demand when the user clicks an info affordance',
      'Content that must be selectable or contain a link, where a hover Tooltip would be unreachable',
      'Touch-friendly hint surfaces where hover is unavailable',
    ],
    whenNotToUse: [
      'A passive label that should appear on hover/focus without a click — use Tooltip',
      'A blocking, focus-trapping dialog for a task — use Modal',
      'Rich forms or pickers anchored to a trigger — use Popover',
      'A list of one-shot actions behind a button — use MenuButton',
    ],
    antiPatterns: [
      {
        bad: 'Using a hover Tooltip to hold a link or text the user needs to read or copy',
        good: 'Use a Toggletip so the content stays open on click and remains reachable and selectable',
        why: 'Hover tooltips disappear on pointer-out and are not keyboard- or touch-reachable for interaction, so interactive or copyable content needs a click-toggled bubble',
      },
      {
        bad: 'Giving the trigger an icon with no text and no labels.label override',
        good: 'Provide labels.label or rely on the built-in i18n accessible name',
        why: 'An icon-only button with no accessible name cannot be operated by screen-reader or voice users',
      },
    ],
    related: [
      {
        name: 'Tooltip',
        relationship: 'alternative',
        reason: 'Use Tooltip for non-interactive hints shown on hover/focus rather than click',
      },
      {
        name: 'Popover',
        relationship: 'alternative',
        reason: 'Use Popover for richer interactive content like forms or pickers',
      },
      {
        name: 'MenuButton',
        relationship: 'alternative',
        reason: 'Use MenuButton when the trigger should reveal a list of actions',
      },
    ],
    a11yRationale:
      'The trigger is a real <button> with aria-expanded reflecting open state and aria-controls pointing at the bubble; an icon-only trigger gets an accessible name from labels.label or the built-in i18n catalog. The bubble is role="status" so its content is announced when it opens, and unlike a hover tooltip the content remains visible and reachable for selection and links. DismissableLayer provides Escape and outside-pointer dismissal, and high-contrast and reduced-motion preferences are honored in CSS.',
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Trigger and bubble styling must resolve to the listed --cascivo-* tokens',
      },
      {
        area: 'content',
        level: 'flexible',
        note: 'trigger and children accept arbitrary ReactNode supplied by the consumer',
      },
      {
        area: 'open state ownership',
        level: 'flexible',
        note: 'Use uncontrolled (defaultOpen) or controlled (open + onOpenChange) as needed',
      },
    ],
  },
}
